
import { MediaItem } from './types';

// Helper function to extract the show name from a title string
function parseShowName(title: string): string | undefined {
    // List of known shows for accurate parsing. This prevents misidentifying movies with hyphens.
    const knownShows = [
        'Gomer Pyle, USMC', 'Hogan’s Heroes', 'My Three Sons', 'Green Acres',
        'Sanford and Son', 'Doctor Who', 'Columbo', 'The Munsters', 'Kojak',
        'The Hardy Boys - Nancy Drew Mysteries', 'Doctor at Large', 'Doctor in Charge',
        'Tales from the Darkside', 'The Three Stooges', 'Get Smart', 'Vega$',
        'The Outer Limits', 'Fraggle Rock', 'I Dream of Jeannie', 'The Bionic Woman',
        'Lexx', 'Most Extreme Elimination Challenge', 'The Andy Griffith Show',
        'Barney Miller', 'Have Gun – Will Travel', 'The Life and Legend of Wyatt Earp',
        'Ancient Aliens'
    ];

    for (const knownShow of knownShows) {
        if (title.startsWith(knownShow)) {
            return knownShow;
        }
    }
    
    return undefined;
}


